CREATE TYPE "public"."match_status" AS ENUM('scheduled', 'live', 'finished', 'postponed', 'cancelled');
CREATE TYPE "public"."user_role" AS ENUM('user', 'admin');
CREATE TABLE "users" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "clerk_user_id" varchar(255) NOT NULL, "display_name" varchar(120) NOT NULL, "avatar_url" varchar(1000), "role" "user_role" DEFAULT 'user' NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "matches" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "api_fixture_id" integer NOT NULL, "competition_id" integer NOT NULL, "competition_name" varchar(255) NOT NULL, "season" integer NOT NULL, "round" varchar(255), "match_date" timestamp with time zone NOT NULL, "home_team_id" integer NOT NULL, "home_team_name" varchar(120) NOT NULL, "away_team_id" integer NOT NULL, "away_team_name" varchar(120) NOT NULL, "home_score" integer, "away_score" integer, "status" "match_status" DEFAULT 'scheduled' NOT NULL, "is_finished" boolean DEFAULT false NOT NULL, "is_active" boolean DEFAULT true NOT NULL, "manual_override" boolean DEFAULT false NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "predictions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "match_id" uuid NOT NULL, "user_id" uuid NOT NULL, "predicted_home_score" integer NOT NULL, "predicted_away_score" integer NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL, CONSTRAINT "predictions_match_user_uq" UNIQUE("match_id","user_id"));
ALTER TABLE "predictions" ADD CONSTRAINT "predictions_match_id_matches_id_fk" FOREIGN KEY ("match_id") REFERENCES "public"."matches"("id") ON DELETE cascade;
ALTER TABLE "predictions" ADD CONSTRAINT "predictions_user_id_users_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE cascade;
CREATE UNIQUE INDEX "users_clerk_user_id_uq" ON "users" USING btree ("clerk_user_id"); CREATE UNIQUE INDEX "matches_api_fixture_id_uq" ON "matches" USING btree ("api_fixture_id"); CREATE INDEX "matches_match_date_idx" ON "matches" USING btree ("match_date"); CREATE INDEX "predictions_match_idx" ON "predictions" USING btree ("match_id"); CREATE INDEX "predictions_user_idx" ON "predictions" USING btree ("user_id");
